def semver_sort(versions):
    def parse(v):
        core = v
        pre = None
        if '+' in core:
            core = core.split('+', 1)[0]
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = (int(x) for x in core.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return major, minor, patch, pre_ids

    def id_key(identifier):
        if identifier.isdigit():
            return (0, int(identifier))
        return (1, identifier)

    def key(v):
        major, minor, patch, pre_ids = parse(v)
        if pre_ids is None:
            pre_key = (1,)
        else:
            pre_key = (0, tuple(id_key(x) for x in pre_ids), len(pre_ids))
        return (major, minor, patch, pre_key)

    return sorted(versions, key=key)

